// Nodo "Configuración" del flujo "Secretaria · Recordatorio de archivos": lo que se toca a mano está aquí.
// Los demás nodos leen estos valores con $('Configuración').first().json.config
// Los SECRETOS no están aquí: el número de destino se lee del entorno de n8n (WHATSAPP_NUMERO_PERMITIDO, definido en el .env)
// y el token de envío va en una credencial de n8n (Header Auth), no aquí.

// Los identificadores (no son secretos) se leen del .env del servidor, así se ponen UNA vez para todos los flujos.
// Si una variable no está en el .env, vale lo que esté escrito aquí abajo.
const delEntorno = (clave, porDefecto) => {
  try {
    return String($env[clave] ?? '').trim() || porDefecto;
  } catch (e) {
    return porDefecto;
  }
};

// === Valores fáciles de cambiar ===
// Project URL de Supabase (Integrations > Data API), sin /rest/v1 al final. No es un secreto.
const SUPABASE_URL = delEntorno('SUPABASE_URL', 'https://TU-PROYECTO.supabase.co');
// Identificador del número de WhatsApp desde el que se envía (WhatsApp > API Setup > Phone number ID). No es un secreto.
const PHONE_NUMBER_ID = delEntorno('WHATSAPP_PHONE_NUMBER_ID', 'TU-PHONE-NUMBER-ID');
// Versión de la API Graph de Meta (la misma que en el flujo "Secretaria · WhatsApp")
const GRAPH_VERSION = 'v26.0';
// Horas que un archivo lleva sin clasificar para que se te pregunte por él. Antes de eso no se molesta: acabas de mandarlo.
const HORAS_ESPERA = 24;
// Horas desde el último mensaje tuyo durante las que Meta admite texto libre. Fuera de ese plazo NO se envía nada (el resumen
// de las 7:00 ya lista estos archivos y no hay plantilla para este recordatorio).
const VENTANA_HORAS = 23;
// Archivos que se nombran en el mensaje; el resto se resume como «y N más».
const MAX_LISTA = 10;
// ==================================

if (!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(SUPABASE_URL) || SUPABASE_URL.includes('TU-PROYECTO')) {
  throw new Error('Configuración: pon tu Project URL de Supabase en SUPABASE_URL (https://<ref>.supabase.co, sin /rest/v1). Va en el .env del servidor (SUPABASE_URL=…, y después docker compose up -d)');
}
if (!/^\d{8,20}$/.test(PHONE_NUMBER_ID)) {
  throw new Error('Configuración: pon el Phone number ID de WhatsApp en PHONE_NUMBER_ID (solo dígitos). Va en el .env del servidor (WHATSAPP_PHONE_NUMBER_ID=…, y después docker compose up -d)');
}
if (!/^v\d+\.\d+$/.test(GRAPH_VERSION)) {
  throw new Error('Configuración: GRAPH_VERSION debe tener la forma v26.0');
}
if (!Number.isFinite(HORAS_ESPERA) || HORAS_ESPERA < 1 || HORAS_ESPERA > 720) {
  throw new Error('Configuración: HORAS_ESPERA debe estar entre 1 y 720');
}
if (!Number.isFinite(VENTANA_HORAS) || VENTANA_HORAS < 1 || VENTANA_HORAS > 24) {
  throw new Error('Configuración: VENTANA_HORAS debe estar entre 1 y 24');
}
if (!Number.isInteger(MAX_LISTA) || MAX_LISTA < 1 || MAX_LISTA > 30) {
  throw new Error('Configuración: MAX_LISTA debe estar entre 1 y 30');
}

return [
  {
    json: {
      config: {
        supabase_url: SUPABASE_URL.replace(/\/+$/, ''),
        phone_number_id: PHONE_NUMBER_ID,
        graph_version: GRAPH_VERSION,
        horas_espera: HORAS_ESPERA,
        ventana_horas: VENTANA_HORAS,
        max_lista: MAX_LISTA,
      },
    },
  },
];

// Nodo "Filtrar archivos": de lo que devolvió Supabase se queda con los archivos que llevan sin clasificar más de HORAS_ESPERA.
//
// La consulta ya filtra, pero cada fila se revalida aquí (pendiente, nombre, fecha válida y de hace más de la espera): así un
// archivo recién mandado nunca provoca una pregunta. Si no queda ninguno devuelve [] y el flujo termina sin leer nada más.

const config = $('Configuración').first().json.config;
const ahora = Date.now();
const limite = ahora - config.horas_espera * 3600 * 1000;

const archivos = $input
  .all()
  .map((i) => i.json)
  .filter((r) => r && r.estado === 'pendiente' && typeof r.nombre === 'string' && r.nombre.trim() !== '' && typeof r.created_at === 'string' && Date.parse(r.created_at) <= limite)
  .sort((a, b) => Date.parse(a.created_at) - Date.parse(b.created_at))
  .map((r) => ({ nombre: r.nombre, created_at: r.created_at }));

if (archivos.length === 0) return [];
return [{ json: { archivos } }];

// Nodo "Redactar recordatorio": UN mensaje de WhatsApp con los archivos que llevan días sin clasificar, y el cuerpo exacto de la
// petición a Meta.
//
// - Solo se envía como texto libre y solo si la ventana de 24 h de Meta sigue abierta (el último mensaje TUYO es de hace menos de
//   VENTANA_HORAS). Si está cerrada devuelve [] y no se envía nada: el resumen de las 7:00 ya los lista.
// - El mensaje explica cómo clasificarlos: no hace falta estado nuevo, la respuesta pasa por la intención «archivar» del flujo
//   principal (órdenes en bloque: «las N últimas son de …», «todas en …»).
// - Se redacta con código, nunca con el modelo.

const config = $('Configuración').first().json.config;
const LIMITE_MENSAJE = 3800;
const ZONA = 'Europe/Madrid';

const limpiar = (s) => String(s ?? '').replace(/[*_~`]/g, '').replace(/\s+/g, ' ').trim();
const fmtFecha = new Intl.DateTimeFormat('es-ES', { timeZone: ZONA, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const fecha = (iso) => fmtFecha.format(new Date(iso)).replace(/\./g, '').replace(',', '');

const archivos = $('Filtrar archivos').first().json.archivos;
const ultimo = $('Leer último mensaje')
  .all()
  .map((x) => x.json)
  .filter((r) => r && typeof r.created_at === 'string')
  .map((r) => new Date(r.created_at))
  .filter((d) => !Number.isNaN(d.getTime()))[0];

const ahora = new Date();
const ventanaAbierta = Boolean(ultimo) && ahora.getTime() - ultimo.getTime() < config.ventana_horas * 3600 * 1000;
if (!ventanaAbierta) return [];

const para = String($env.WHATSAPP_NUMERO_PERMITIDO ?? '').replace(/\D/g, '');
if (!para) throw new Error('Redactar recordatorio: falta WHATSAPP_NUMERO_PERMITIDO en el entorno de n8n');

const n = archivos.length;
const cabecera = n === 1 ? '📎 Tienes *1 archivo* sin clasificar desde hace más de un día:' : `📎 Tienes *${n} archivos* sin clasificar desde hace más de un día:`;
const mostrados = archivos.slice(0, config.max_lista);
const lista = mostrados.map((a) => `• ${limpiar(a.nombre)} (${fecha(a.created_at)})`).join('\n');
const resto = n > mostrados.length ? `\n• y ${n - mostrados.length} más` : '';
const quien = n > 1 ? `las ${Math.min(n, 3)} últimas son` : 'la última es';
const pie = `Respóndeme, por ejemplo, «${quien} la factura de la luz» o «${n > 1 ? 'todas en Fotos' : 'guárdala en Fotos'}».`;

let texto = `${cabecera}\n${lista}${resto}\n\n${pie}`;
if (texto.length > LIMITE_MENSAJE) texto = `${texto.slice(0, LIMITE_MENSAJE - 1).trimEnd()}…`;

return [
  {
    json: {
      cuerpo: { messaging_product: 'whatsapp', recipient_type: 'individual', to: para, type: 'text', text: { preview_url: false, body: texto } },
      texto,
      total: n,
    },
  },
];
